                Question(prompt: "How long does it usually take for a fossil to form?",
                         options: ["Millions of years", "One week", "A few days", "One year"], correctIndex: 0,
                         explanation: "Making a fossil is a very slow process that usually takes millions of years. When an animal dies and is buried in mud or sand, minerals slowly seep into its bones and turn them to rock. That is why finding a fossil is like discovering a message from deep in the past."),
                Question(prompt: "What is the special name for fossilised dinosaur poop?",
                         options: ["Meteorite", "Stalactite", "Dynamite", "Coprolite"], correctIndex: 3,
