                Question(prompt: "What tools do paleontologists often use to remove delicate fossils?",
                         options: ["Only bulldozers", "Brushes and small picks", "Spoons and forks", "Vacuum cleaners"], correctIndex: 1,
                         explanation: "Fossils are precious and fragile, so paleontologists dig carefully with small tools like brushes, picks, and chisels. They remove the rock bit by bit so the bones are not damaged. A single big dig can take weeks or even months of slow, patient work."),
                Question(prompt: "Where do many people go to see real dinosaur skeletons?",
                         options: ["A supermarket", "A museum", "A cinema", "A swimming pool"], correctIndex: 1,
